const token = $('Store Token').item.json.accessToken;
const apiBase = $('Store Token').item.json.apiBase;
const slugPayload = $('Get Existing Slugs').item.json;
const slugList = slugPayload?.data || slugPayload || [];
const existingSlugs = new Set(
  (Array.isArray(slugList) ? slugList : [])
    .map((x) => String(x.slug || x.Slug || '').trim().toLowerCase())
    .filter(Boolean)
);

// Persian characters in URL slugs collide and are hard to manage.
// Map known topics to stable ASCII bases; unknown Persian topics get hashed ASCII.
const TOPIC_SLUGS = {
  'ظروف کریستال': 'crystal-tableware',
  'ظروف کریستال پذیرایی': 'crystal-hospitality-ware',
  'ظروف دکوری': 'decorative-crystal',
  'ظروف دکوری کریستال': 'decorative-crystal-ware',
  'خرید ظروف کریستال': 'buy-crystal-tableware',
  'نگهداری ظروف کریستال': 'crystal-care-guide',
  'تفاوت کریستال و شیشه': 'crystal-vs-glass',
  'هدیه ظروف کریستال': 'crystal-gift-guide',
  'چیدمان میز کریستال': 'crystal-table-setting',
  'ظروف کریستال عروس': 'bridal-crystal-set',
  'قیمت ظروف کریستال': 'crystal-tableware-price',
  'شستشوی ظروف کریستال': 'washing-crystal-glassware'
};

const toAsciiSlug = (value) => {
  const raw = String(value || '').trim();
  if (!raw) return 'blog';
  if (TOPIC_SLUGS[raw]) return TOPIC_SLUGS[raw];
  let slug = raw
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
  if (!slug || /[\u0600-\u06FF]/.test(raw)) {
    let h = 0;
    for (let i = 0; i < raw.length; i++) h = ((h << 5) - h + raw.charCodeAt(i)) | 0;
    slug = 'topic-' + Math.abs(h).toString(36);
  }
  return slug.slice(0, 80) || 'blog';
};

const allocateUnique = (base) => {
  const root = (base || 'blog').slice(0, 70);
  if (!existingSlugs.has(root)) return root;
  for (let n = 2; n <= 199; n++) {
    const c = root + '-' + n;
    if (!existingSlugs.has(c)) return c;
  }
  return root + '-' + Date.now().toString(36);
};

const fallbackKeywords = Object.keys(TOPIC_SLUGS);
let keywords = fallbackKeywords.slice();
try {
  const seedRaw = $('Config').item.json.seedTopics;
  const parsed = typeof seedRaw === 'string' ? JSON.parse(seedRaw) : seedRaw;
  if (Array.isArray(parsed) && parsed.length) keywords = [...parsed.map(String), ...fallbackKeywords];
} catch (e) {}
try {
  const suggest = $('Keyword Suggest').item.json;
  if (Array.isArray(suggest?.[1]) && suggest[1].length) {
    keywords = [...suggest[1].map(String).slice(0, 15), ...keywords];
  }
} catch (e) {}

const seenKw = new Set();
keywords = keywords.filter((k) => {
  const key = String(k).trim();
  if (!key || seenKw.has(key)) return false;
  seenKw.add(key);
  return true;
});

const free = [];
for (const k of keywords) {
  const base = toAsciiSlug(k);
  if (!existingSlugs.has(base)) free.push({ keyword: k, slug: base });
}

let pick;
let slug;
if (free.length) {
  const idx = (new Date().getDate() + existingSlugs.size) % free.length;
  pick = free[idx].keyword;
  slug = allocateUnique(free[idx].slug);
} else {
  pick = keywords[0] || 'ظروف کریستال';
  slug = allocateUnique(toAsciiSlug(pick));
}

if (existingSlugs.has(slug)) {
  slug = allocateUnique(slug + '-' + Date.now().toString(36).slice(-4));
}

return [{
  json: {
    token,
    apiBase,
    candidateKeywords: keywords,
    selectedKeyword: pick,
    selectedTopic: pick,
    slug,
    existingSlugCount: existingSlugs.size,
    freeTopicCount: free.length
  }
}];

const raw = $('Generate Article (LLM)').item.json;
const content = raw.choices?.[0]?.message?.content || '{}';
const extractJson = (text) => {
  let s = String(text || '').trim();
  // Strip markdown fences: ```json ... ```
  const fenced = s.match(/```(?:json|JSON)?\s*([\s\S]*?)```/);
  if (fenced?.[1]) s = fenced[1].trim();
  // If still wrapped with prose, take first {...} object
  if (!s.startsWith('{')) {
    const start = s.indexOf('{');
    const end = s.lastIndexOf('}');
    if (start >= 0 && end > start) s = s.slice(start, end + 1);
  }
  return s;
};
let article;
try {
  article = JSON.parse(extractJson(content));
} catch (e) {
  throw new Error('LLM did not return valid JSON: ' + String(e.message || e).slice(0, 180));
}
const ctx = $('Select Topic').item.json;
const keyword = ctx.selectedKeyword || 'ظروف کریستال';

const stripHtml = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
const ensureMeta = (s, fallback) => {
  let t = String(s || fallback || '').trim();
  if (t.length < 70) {
    t = `${t} راهنمای کاربردی خرید، نگهداری و چیدمان ${keyword} برای خانه و پذیرایی.`.replace(/\s+/g, ' ').trim();
  }
  if (t.length > 160) t = t.slice(0, 157).trim() + '...';
  if (t.length < 70) t = (t + ' راهنمای کامل ظروف کریستال و دکوری برای خرید هوشمند.').slice(0, 160);
  return t;
};
const ensureContent = (html) => {
  let c = String(html || '').trim();
  if (!/href\s*=\s*["'][^"']*\/(products|categories|blog)\//i.test(c)) {
    c = `<p>برای دیدن گزینه‌های مرتبط، به <a href="/categories/">دسته‌بندی ظروف</a> سر بزنید.</p>` + c;
  }
  if (!/<h2[^>]*>\s*(سوالات متداول|پرسش‌های متداول|faq)/i.test(c)) {
    c += `<h2>سوالات متداول</h2>
<h3>${keyword} برای چه استفاده‌ای مناسب است؟</h3>
<p>بیشتر برای پذیرایی، دکوراسیون میز و هدیه کاربرد دارد و اگر درست نگهداری شود ظاهر شفاف خود را حفظ می‌کند.</p>
<h3>چطور ${keyword} را بشوییم؟</h3>
<p>شستشوی دستی با اسفنج نرم و شوینده ملایم معمولاً ایمن‌تر است؛ از ضربه‌های ناگهانی و شوک دمایی شدید پرهیز کنید.</p>
<h3>موقع خرید به چه نکاتی توجه کنیم؟</h3>
<p>شفافیت، ضخامت بدنه، ایستایی پایه و هماهنگی با بقیه ظروف روی میز از مهم‌ترین معیارها هستند.</p>
<h3>آیا برای هدیه مناسب است؟</h3>
<p>بله، مخصوصاً اگر بسته‌بندی محکم و ظاهر شکیل داشته باشد و با سلیقه میزبان هماهنگ باشد.</p>
<h3>چطور براقیت آن حفظ شود؟</h3>
<p>بعد از شستشو با پارچه نرم خشک کنید و از اسکاچ زبر یا مواد بسیار اسیدی دوری کنید.</p>`;
  }
  let guard = 0;
  while (stripHtml(c).length < 520 && guard < 8) {
    c += `<p>در انتخاب ${keyword} بهتر است به کاربرد واقعی میز، فضای پذیرایی و راحتی نگهداری فکر کنید. مدل‌های ساده‌تر معمولاً همه‌کاره‌ترند و با سرویس‌های مختلف بهتر ست می‌شوند.</p>`;
    guard += 1;
  }
  return c;
};

const introFa = article.introFa || `اگر به دنبال ${keyword} هستید، این راهنما کمک می‌کند انتخاب کاربردی‌تری داشته باشید و بعد از خرید هم بهتر از آن نگهداری کنید.`;
const conclusionFa = article.conclusionFa || `در نهایت، ${keyword} وقتی ارزش خرید دارد که هم با فضای خانه هماهنگ باشد و هم نگهداری‌اش برای شما سخت نباشد.`;
const contentFa = ensureContent(article.contentFa);
const metaDescriptionFa = ensureMeta(article.metaDescriptionFa, introFa);
const excerptFa = ensureMeta(article.excerptFa || metaDescriptionFa, metaDescriptionFa).slice(0, 160);

const normalized = {
  ...article,
  titleFa: article.titleFa || keyword,
  introFa,
  contentFa,
  conclusionFa,
  excerptFa,
  metaDescriptionFa,
  metaKeywordsFa: article.metaKeywordsFa || `${keyword}, ظروف کریستال, ظروف دکوری, خرید ظروف`,
  titleEn: article.titleEn || keyword,
  introEn: article.introEn || introFa,
  contentEn: ensureContent(article.contentEn || contentFa),
  conclusionEn: article.conclusionEn || conclusionFa,
  excerptEn: ensureMeta(article.excerptEn || article.metaDescriptionEn || excerptFa, excerptFa).slice(0, 160),
  metaDescriptionEn: ensureMeta(article.metaDescriptionEn || metaDescriptionFa, metaDescriptionFa),
  metaKeywordsEn: article.metaKeywordsEn || article.metaKeywordsFa || keyword,
  slug: ctx.slug /* locked unique ASCII slug */,
  primaryKeyword: keyword,
};

return [{
  json: {
    ...ctx,
    article: normalized,
  }
}];

